package app.aaps.implementation.notifications

/**
 * Soft alarm melodies generated by code (no audio file to ship), for people who find the default alarm
 * too aggressive. Each one loops: it starts and ends in silence. See [AlarmMelodySynth].
 *
 * [id] is the stored preference value (`StringKey.AlertSoundLowGlucose` / `AlertSoundOtherAlarms`).
 */
enum class AlarmMelody(val id: String, val durationMs: Long) {

    /** Four rising bell notes, light. */
    SOFT_CHIME("soft_chime", 4_000L),

    /** Three low bells with a long ring. */
    WARM_BELLS("warm_bells", 4_000L),

    /** Short wooden notes, like a marimba. */
    MARIMBA("marimba", 4_000L),

    /** One soft tone, pulsing slowly. */
    GENTLE_PULSE("gentle_pulse", 4_000L);

    companion object {

        /** Preference value of the AAPS sound itself. */
        const val DEFAULT_CHOICE = "default"

        /** The melody of a stored choice, `null` for the AAPS sound or an unknown value. */
        fun fromChoice(choice: String?): AlarmMelody? = entries.firstOrNull { it.id == choice }
    }
}
